import json, time, urllib.request, urllib.error
from datetime import datetime, timezone
from decimal import Decimal, ROUND_HALF_UP

BASE = "http://localhost:8080"
LOG = []

def req(method, path, token=None):
    headers = {"Authorization": f"Bearer {token}"} if token else {}
    r = urllib.request.Request(BASE + path, method=method, headers=headers)
    while True:
        try:
            with urllib.request.urlopen(r, timeout=30) as resp:
                return resp.status, json.loads(resp.read() or b"null"), dict(resp.headers)
        except urllib.error.HTTPError as e:
            body = e.read()
            hdrs = dict(e.headers)
            LOG.append((path, e.code, body[:200].decode(errors="replace"), hdrs.get("Retry-After")))
            if e.code == 429 or e.code == 503:
                wait = hdrs.get("Retry-After")
                wait = float(wait) if wait else 1.0
                time.sleep(wait)
                continue
            if e.code == 401:
                return 401, None, hdrs
            if e.code == 404:
                return 404, None, hdrs
            time.sleep(1)
            continue
        except urllib.error.URLError as e:
            LOG.append((path, "URLError", str(e)[:200], None))
            time.sleep(1)
            continue

token = None
def get_token():
    global token
    _, body, _ = req("POST", "/token")
    token = body["token"]
    return token

def authed(path):
    global token
    if token is None:
        get_token()
    for _ in range(5):
        status, body, hdrs = req("GET", path, token)
        if status == 401:
            get_token()
            continue
        if status == 404:
            return 404, None
        return status, body
    raise RuntimeError(f"gave up on {path}")

# Pull all order pages
orders = {}
dupes = 0
seen_listing_ids = []
page = 1
total_pages = None
while True:
    status, body = authed(f"/orders?page={page}")
    assert status == 200, (page, status)
    total_pages = body["total_pages"]
    for it in body["items"]:
        seen_listing_ids.append(it["id"])
        if it["id"] in orders:
            dupes += 1
        else:
            orders[it["id"]] = it
    if page >= total_pages or body.get("next") is None and page >= total_pages:
        break
    page += 1

print("pages:", total_pages, "fetched through page", page)
print("listing rows:", len(seen_listing_ids), "distinct:", len(orders), "dupes:", dupes)

START = datetime(2025, 3, 1, tzinfo=timezone.utc)
END_EXCL = datetime(2025, 6, 1, tzinfo=timezone.utc)

def parse_ts(s):
    dt = datetime.fromisoformat(s.replace("Z", "+00:00"))
    if dt.tzinfo is None:
        raise ValueError(f"naive timestamp {s}")
    return dt.astimezone(timezone.utc)

customers = {}
def customer(cid):
    if cid not in customers:
        status, body = authed(f"/customers/{cid}")
        customers[cid] = body if status == 200 else {"_missing": True, "status": status}
    return customers[cid]

qualifying = []
status_counts = {}
for o in orders.values():
    status_counts[o["status"]] = status_counts.get(o["status"], 0) + 1
    if o["status"] != "shipped":
        continue
    ts = parse_ts(o["placed_at"])
    if not (START <= ts < END_EXCL):
        continue
    qualifying.append(o)

print("status counts (distinct):", status_counts)
print("qualifying orders:", len(qualifying))

by_region = {"north": 0, "south": 0, "east": 0, "west": 0}
total = 0
problems = []
for o in qualifying:
    c = customer(o["customer_id"])
    if c.get("_missing"):
        problems.append((o["id"], o["customer_id"], c))
        continue
    pct = Decimal(c["discount_pct"])
    amt = Decimal(o["amount_cents"]) * (Decimal(100) - pct) / Decimal(100)
    rounded = int(amt.quantize(Decimal("1"), rounding=ROUND_HALF_UP))
    total += rounded
    by_region[c["region"]] += rounded

print("customers fetched:", len(customers))
print("problems:", problems)
print("retry log entries:", len(LOG))
for e in LOG[:20]:
    print("  ", e)

result = {
    "total_cents": total,
    "order_count": len(qualifying),
    "duplicates_skipped": dupes,
    "by_region": by_region,
}
assert sum(by_region.values()) == total
with open("/workspace/result.json", "w") as f:
    json.dump(result, f, indent=2)
    f.write("\n")
print(json.dumps(result, indent=2))
EOF
cd /tmp/work && timeout 900 python3 -I recon.py

